INSERT INTO ui_messages (key, language_code, text) VALUES
  ('scheme.rejection.label.aadhaar_seeding_mismatch','en','Aadhaar not seeded to the bank account'),
  ('scheme.rejection.label.aadhaar_seeding_mismatch','hi','बैंक खाते से आधार जुड़ा नहीं'),
  ('scheme.rejection.label.aadhaar_seeding_mismatch','gu','બેંક ખાતા સાથે આધાર જોડાયેલું નથી'),
  ('scheme.rejection.fix.aadhaar_seeding_mismatch','en','One visit to the bank: ask for Aadhaar seeding (NPCI mapping) on the account, then resubmit.'),
  ('scheme.rejection.fix.aadhaar_seeding_mismatch','hi','बैंक का एक चक्कर: खाते में आधार सीडिंग (NPCI मैपिंग) करवाएँ, फिर दोबारा जमा करें।'),
  ('scheme.rejection.fix.aadhaar_seeding_mismatch','gu','બેંકની એક મુલાકાત: ખાતામાં આધાર સીડિંગ (NPCI મેપિંગ) કરાવો, પછી ફરી સબમિટ કરો.'),
  ('scheme.rejection.label.land_record_name_variance','en','Name differs between Aadhaar and the land record'),
  ('scheme.rejection.label.land_record_name_variance','hi','आधार और भूमि रिकॉर्ड में नाम अलग'),
  ('scheme.rejection.label.land_record_name_variance','gu','આધાર અને જમીન રેકોર્ડમાં નામ અલગ'),
  ('scheme.rejection.fix.land_record_name_variance','en','Get the spelling corrected at the talati / revenue office (or an affidavit), then resubmit with the corrected record.'),
  ('scheme.rejection.fix.land_record_name_variance','hi','तलाटी / राजस्व कार्यालय में नाम की वर्तनी सुधरवाएँ (या शपथ-पत्र), फिर सुधरे रिकॉर्ड के साथ दोबारा जमा करें।'),
  ('scheme.rejection.fix.land_record_name_variance','gu','તલાટી / મહેસૂલ કચેરીમાં નામની જોડણી સુધારાવો (અથવા સોગંદનામું), પછી સુધારેલા રેકોર્ડ સાથે ફરી સબમિટ કરો.'),
  ('scheme.rejection.label.duplicate_application','en','A duplicate application'),
  ('scheme.rejection.label.duplicate_application','hi','दोहराया गया आवेदन'),
  ('scheme.rejection.label.duplicate_application','gu','બેવડી અરજી'),
  ('scheme.rejection.fix.duplicate_application','en','Track the earlier application instead — nothing to refile.'),
  ('scheme.rejection.fix.duplicate_application','hi','पहले वाले आवेदन की स्थिति देखें — दोबारा भरने की ज़रूरत नहीं।'),
  ('scheme.rejection.fix.duplicate_application','gu','પહેલાની અરજીની સ્થિતિ જુઓ — ફરી ભરવાની જરૂર નથી.'),
  ('scheme.rejection.label.window_missed','en','The application window had closed'),
  ('scheme.rejection.label.window_missed','hi','आवेदन की अवधि समाप्त हो चुकी थी'),
  ('scheme.rejection.label.window_missed','gu','અરજીનો સમયગાળો પૂરો થઈ ગયો હતો'),
  ('scheme.rejection.fix.window_missed','en','Apply in the next window — the desk lists when it opens.'),
  ('scheme.rejection.fix.window_missed','hi','अगली अवधि में आवेदन करें — डेस्क बताता है कब खुलेगी।'),
  ('scheme.rejection.fix.window_missed','gu','આગામી સમયગાળામાં અરજી કરો — ડેસ્ક જણાવે છે ક્યારે ખુલશે.'),
  ('scheme.rejection.label.documents_missing','en','A required document was missing'),
  ('scheme.rejection.label.documents_missing','hi','ज़रूरी दस्तावेज़ नहीं था'),
  ('scheme.rejection.label.documents_missing','gu','જરૂરી દસ્તાવેજ ન હતો'),
  ('scheme.rejection.fix.documents_missing','en','Attach the missing document named by the authority, then appeal or resubmit.'),
  ('scheme.rejection.fix.documents_missing','hi','प्राधिकरण द्वारा बताया गया दस्तावेज़ जोड़ें, फिर अपील करें या दोबारा जमा करें।'),
  ('scheme.rejection.fix.documents_missing','gu','સત્તામંડળે જણાવેલો દસ્તાવેજ જોડો, પછી અપીલ કરો અથવા ફરી સબમિટ કરો.'),
  ('scheme.rejection.label.ineligible_landholding','en','Landholding outside the scheme''s limit'),
  ('scheme.rejection.label.ineligible_landholding','hi','भूमि जोत योजना की सीमा से बाहर'),
  ('scheme.rejection.label.ineligible_landholding','gu','જમીન ધારણ યોજનાની મર્યાદા બહાર'),
  ('scheme.rejection.fix.ineligible_landholding','en','Check the land record on file; if it is wrong, correct it and appeal — otherwise look for a scheme that fits.'),
  ('scheme.rejection.fix.ineligible_landholding','hi','दर्ज भूमि रिकॉर्ड जाँचें; ग़लत हो तो सुधरवाकर अपील करें — वरना उपयुक्त योजना देखें।'),
  ('scheme.rejection.fix.ineligible_landholding','gu','નોંધાયેલો જમીન રેકોર્ડ તપાસો; ખોટો હોય તો સુધારીને અપીલ કરો — નહીંતર યોગ્ય યોજના જુઓ.'),
  ('scheme.rejection.label.ineligible_category','en','Category not covered by the scheme'),
  ('scheme.rejection.label.ineligible_category','hi','श्रेणी योजना में शामिल नहीं'),
  ('scheme.rejection.label.ineligible_category','gu','શ્રેણી યોજનામાં સામેલ નથી'),
  ('scheme.rejection.fix.ineligible_category','en','Confirm the category certificate on file; if it is missing or wrong, update it and appeal.'),
  ('scheme.rejection.fix.ineligible_category','hi','दर्ज श्रेणी प्रमाणपत्र की पुष्टि करें; न हो या ग़लत हो तो अपडेट करके अपील करें।'),
  ('scheme.rejection.fix.ineligible_category','gu','નોંધાયેલું શ્રેણી પ્રમાણપત્ર ચકાસો; ન હોય કે ખોટું હોય તો અપડેટ કરીને અપીલ કરો.'),
  ('scheme.rejection.label.ineligible_region','en','Region not covered by the scheme'),
  ('scheme.rejection.label.ineligible_region','hi','क्षेत्र योजना में शामिल नहीं'),
  ('scheme.rejection.label.ineligible_region','gu','વિસ્તાર યોજનામાં સામેલ નથી'),
  ('scheme.rejection.fix.ineligible_region','en','Check the address and land location on file; apply only where the scheme runs.'),
  ('scheme.rejection.fix.ineligible_region','hi','दर्ज पता और भूमि का स्थान जाँचें; केवल वहाँ आवेदन करें जहाँ योजना चलती है।'),
  ('scheme.rejection.fix.ineligible_region','gu','નોંધાયેલું સરનામું અને જમીનનું સ્થાન તપાસો; ફક્ત જ્યાં યોજના ચાલે છે ત્યાં અરજી કરો.'),
  ('scheme.rejection.label.portal_rejected','en','Rejected by the government portal'),
  ('scheme.rejection.label.portal_rejected','hi','सरकारी पोर्टल द्वारा अस्वीकृत'),
  ('scheme.rejection.label.portal_rejected','gu','સરકારી પોર્ટલ દ્વારા નામંજૂર'),
  ('scheme.rejection.fix.portal_rejected','en','Read the portal''s remark on the acknowledgement, fix what it names, and resubmit or appeal.'),
  ('scheme.rejection.fix.portal_rejected','hi','पावती पर पोर्टल की टिप्पणी पढ़ें, बताई गई कमी ठीक करें, फिर दोबारा जमा करें या अपील करें।'),
  ('scheme.rejection.fix.portal_rejected','gu','પાવતી પર પોર્ટલની ટિપ્પણી વાંચો, જણાવેલી ખામી સુધારો, પછી ફરી સબમિટ કરો અથવા અપીલ કરો.'),
  ('scheme.rejection.label.withdrawn_by_applicant','en','Withdrawn by the applicant'),
  ('scheme.rejection.label.withdrawn_by_applicant','hi','आवेदक द्वारा वापस लिया गया'),
  ('scheme.rejection.label.withdrawn_by_applicant','gu','અરજદાર દ્વારા પાછી ખેંચાઈ'),
  ('scheme.rejection.fix.withdrawn_by_applicant','en','Nothing to fix — apply again whenever the member wants to.'),
  ('scheme.rejection.fix.withdrawn_by_applicant','hi','कुछ ठीक नहीं करना — सदस्य जब चाहें फिर आवेदन करें।'),
  ('scheme.rejection.fix.withdrawn_by_applicant','gu','કંઈ સુધારવાનું નથી — સભ્ય ઇચ્છે ત્યારે ફરી અરજી કરો.'),
  ('scheme.rejection.label.other','en','Another reason (see the officer''s note)'),
  ('scheme.rejection.label.other','hi','अन्य कारण (अधिकारी की टिप्पणी देखें)'),
  ('scheme.rejection.label.other','gu','અન્ય કારણ (અધિકારીની ટિપ્પણી જુઓ)'),
  ('scheme.rejection.fix.other','en','Read the officer''s note with the member and fix what it names; the desk can help with the appeal.'),
  ('scheme.rejection.fix.other','hi','सदस्य के साथ अधिकारी की टिप्पणी पढ़ें और बताई गई बात ठीक करें; अपील में डेस्क मदद कर सकता है।'),
  ('scheme.rejection.fix.other','gu','સભ્ય સાથે અધિકારીની ટિપ્પણી વાંચો અને જણાવેલી બાબત સુધારો; અપીલમાં ડેસ્ક મદદ કરી શકે છે.')
